'use strict';
const D=window.REGION_DATA,P=new Map(D.projects.map(p=>[p.id,p])),cache=new Map(),pending=new Map(),main=document.querySelector('#main');
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=v=>v===null||v===undefined?'미확인':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:2});
const link=(p,route='project')=>'#'+route+'/'+encodeURIComponent(p.id),pill=(s,c='original')=>`<span class="pill ${c}">${E(s)}</span>`;
const heading=(t,s)=>`<div class="page-heading illustrated-heading"><img class="section-art" src="assets/${t==='지식그래프'?'evidence-network':'evidence-library'}.svg" alt=""><div class="eyebrow">PROJECT EVIDENCE ATLAS</div><h1>${t}</h1><p>${s}</p></div>`;
const quote=s=>`<div class="quote">${E(s||'원문 기재 확인 안 됨')}</div>`;
const meta=(s,l)=>`<div class="source-meta">${E(s)}<br>${E(l)}</div>`;
const url=u=>/^https?:\/\//i.test(u||'')?E(u):'';
const budgets=p=>`<div class="budgets">${[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']].map(([k,t])=>`<div class="budget-card"><div class="label">${t}</div><strong>${N(p[k])}<span class="unit">${p[k]==null?'':'억원'}</span></strong>${pill(p[k+'_status']||'미확인',p[k]==null?'unknown':'neutral')}</div>`).join('')}</div>`;
window.REGION_PROJECT=data=>{cache.set(data.id,data);if(pending.has(data.id)){pending.get(data.id).resolve(data);pending.delete(data.id)}};
function packet(id){if(cache.has(id))return Promise.resolve(cache.get(id));if(pending.has(id))return pending.get(id).promise;let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});pending.set(id,{promise,resolve,reject});const s=document.createElement('script');s.src='data/projects/'+P.get(id).key+'.js';s.onerror=()=>{pending.delete(id);reject(Error('사업 자료를 불러오지 못했습니다. 새로고침해 주세요.'))};document.head.append(s);return promise}
let sourcesPromise;function sources(){return sourcesPromise??=new Promise((resolve,reject)=>{if(window.REGION_SOURCES)return resolve(window.REGION_SOURCES);let s=document.createElement('script');s.src='data/sources.js';s.onload=()=>resolve(window.REGION_SOURCES);s.onerror=()=>{sourcesPromise=null;reject(Error('공개 자료를 불러오지 못했습니다.'))};document.head.append(s)})}
function evidence(e){return `<article class="evidence-card" id="${E(e.evidence_id)}"><div class="evidence-top"><h3>${E(e.field)}</h3>${pill('원문 기재')}</div><div class="evidence-id">${E(e.evidence_id)}</div>${quote(e.excerpt)}${meta(e.source,e.location)}</article>`}
function publicCard(s,relation){return `<article class="evidence-card"><div class="evidence-top"><h3>${E(s.title)}</h3>${pill('공개자료','public')}</div><div class="source-meta">${E(s.source_id)} · ${E(s.publisher_domain)} · ${E(s.read_level)}</div>${quote(s.excerpt)}${s.direct_fact?quote(s.direct_fact):''}<p class="subtle">${E(relation||s.field_scope||'동일사업 여부 미확인')}</p>${pill('동일사업·재원 관계 미확인','unknown')} ${url(s.url)?`<a class="button" href="${url(s.url)}" target="_blank" rel="noopener noreferrer">공개 출처 열기 ↗</a>`:''}${meta('확인일: '+(s.checked||'미기재'),s.direct_location||'')}</article>`}
function overview(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">REGIONAL DEVELOPMENT · EVIDENCE ATLAS</div><h1>사업에서 근거로,<br>연결해서 살펴보기</h1><p>7개 권역의 1,312개 사업을 검색하고, 원문과 공개자료의 연결을 따라갑니다. 원문 기재·공개자료·규칙 대조·미확인을 구분한 열람본입니다.</p><div class="actions"><a class="button primary" href="#projects">전체 사업 검색 →</a><a class="button" href="#graph">지식그래프 탐색</a></div></div><figure class="atlas-hero-figure"><img src="assets/connected-regions.svg" alt="지역의 도시와 자연, 문서 근거가 연결되는 개념 일러스트"><figcaption>지역과 사업, 그리고 연결된 근거</figcaption></figure></section><div class="metrics">${[[1312,'전체 사업','건'],[7,'권역','개'],[19731,'원문 근거','개'],[1773,'공개 참고자료','개']].map(([n,t,u])=>`<div class="metric"><div class="label">${t}</div><strong>${N(n)}</strong><small>${u}</small></div>`).join('')}</div><div class="section-head"><h2><span class="num">01</span>권역별 사업</h2><a href="#projects">전체 보기 →</a></div><div class="region-cards">${D.regions.map(r=>`<a class="region-card" href="${hubLink('region',r.region)}"><img class="region-art" src="assets/region-${D.regions.indexOf(r)}.svg" alt="" loading="lazy"><h3>${E(r.region)}<span class="arrow">↗</span></h3><strong>${N(r.count)}</strong><small>개 사업</small><div class="bar-track"><i style="width:${r.count/Math.max(...D.regions.map(x=>x.count))*100}%"></i></div></a>`).join('')}</div><div class="section-head"><h2><span class="num">02</span>확인 수준을 함께 읽기</h2></div><div class="card">${levelLegend()}<p>원문에 적혀 있다는 사실과 실제 집행·소관 확정은 구분합니다. 공개자료 1,773개에는 기존 일반 참고자료 89개가 포함되어 있습니다. 사업명 문자열 확인 31건도 동일사업 확정을 뜻하지 않습니다.</p><a class="button" href="#method">확인 기준 자세히 보기 →</a></div><div class="section-head"><h2><span class="num">03</span>권역별 금액 기재 현황</h2><small>단위: 억원</small></div><div class="notice">철도 사업을 포함한 전체 1,312건입니다. 각 금액은 분석표에 기재된 숫자의 합이며, 누락·보류 건을 0으로 처리하지 않았습니다. 기간·범위가 다른 사업을 포함하므로 확정 예산 총액으로 해석하지 않습니다.</div><div class="card table-wrap"><table><thead><tr><th>권역</th><th>사업 수</th><th>전체 사업비</th><th>2027~2032 투자액</th><th>기간 국비 요구액</th></tr></thead><tbody>${D.regions.map(r=>`<tr><td>${E(r.region)}</td><td>${r.count}</td>${['whole','window','national'].map(k=>`<td class="num">${N(r[k])}<span class="count-note">금액 미확인 ${r[k+'_missing']}건</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function levelLegend(){return `<div class="legend">${[['original','원문 기재'],['public','공개자료'],['rule','규칙 대조'],['unknown','미확인']].map(([c,t])=>`<span><i class="dot ${c}"></i>${t}</span>`).join('')}</div>`}
function projects(params){main.innerHTML=heading('사업 검색','사업명·사업 ID·내용·원문 부처 표기를 함께 검색합니다. 금액 단위는 억원입니다.')+`<form id="search-form"><div class="filters"><label>검색어<input name="q" type="search" placeholder="사업명, 기술, 지역, 부처…" value="${E(params.get('q')||'')}"></label><label>권역<select name="region"><option value="">전체 권역</option>${D.regions.map(r=>`<option ${params.get('region')===r.region?'selected':''}>${E(r.region)}</option>`).join('')}</select></label><label>내용 용어<select name="term"><option value="">전체 용어</option>${D.terms.map(t=>`<option>${E(t)}</option>`).join('')}</select></label><label>금액 확인<select name="missing"><option value="">전체</option><option value="yes">미확인 금액 있음</option><option value="no">3개 금액 모두 있음</option></select></label></div><div class="filter-extra"><label>정렬<select name="sort"><option value="original">원자료 순서</option><option value="whole">전체 사업비 큰 순</option><option value="national">국비 요구액 큰 순</option><option value="title">사업명 순</option></select></label><span class="spacer"></span><button type="reset">필터 초기화</button><button class="primary">검색</button></div></form><div id="results"></div>`;const f=document.querySelector('#search-form');let page=1;function draw(){const v=Object.fromEntries(new FormData(f));const qs=v.q.trim().toLowerCase().split(/\s+/).filter(Boolean);let rows=D.projects.filter(p=>(!v.region||p.region===v.region)&&(!v.term||p.terms.some(t=>t.trim()===v.term))&&(!v.missing||(v.missing==='yes'?p.missing>0:p.missing===0))&&qs.every(q=>(p.title+' '+p.id+' '+p.search_text+' '+p.summary_ministry).toLowerCase().includes(q)));if(v.sort==='title')rows.sort((a,b)=>a.title.localeCompare(b.title,'ko'));else if(v.sort!=='original')rows.sort((a,b)=>(b[v.sort]??-Infinity)-(a[v.sort]??-Infinity));window.ACTIVE_SELECTION_RESULTS=rows.map(p=>p.id);const pages=Math.max(1,Math.ceil(rows.length/20));page=Math.min(page,pages);document.querySelector('#results').innerHTML=`<div class="result-heading"><h2>검색 결과 <span class="muted">${N(rows.length)}건</span></h2><small>전체 1,312건</small></div>`+(rows.length?`<div class="card table-wrap"><table class="results-table"><thead><tr><th>사업</th><th>원문 부처 표기</th><th>전체 사업비</th><th>기간 투자액</th><th>기간 국비</th><th>탐색</th></tr></thead><tbody>${rows.slice((page-1)*20,page*20).map(p=>`<tr><td class="project-title"><a href="${link(p)}"><span class="id">${E(p.id)} · ${E(p.category)}</span><strong>${E(p.title)}</strong></a><div class="source-meta">원문 근거 ${p.source_count}개 · ${E(p.public_status)}</div></td><td>${E(p.summary_ministry||'미기재')}</td>${['whole','window','national'].map(k=>`<td class="num">${N(p[k])}</td>`).join('')}<td><a class="button" href="${link(p,'graph')}">그래프</a></td></tr>`).join('')}</tbody></table></div><div class="pagination"><button id="prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages}</span><button id="next" ${page===pages?'disabled':''}>다음 →</button></div>`:`<div class="empty"><h3>검색 결과가 없습니다.</h3>검색어를 줄이거나 필터를 초기화해 주세요.</div>`);document.querySelector('#prev')?.addEventListener('click',()=>{page--;draw()});document.querySelector('#next')?.addEventListener('click',()=>{page++;draw()})}f.onsubmit=e=>{e.preventDefault();page=1;draw()};f.onchange=()=>{page=1;draw()};f.onreset=()=>setTimeout(()=>{page=1;draw()},0);draw()}
async function detail(p,token){const d=await packet(p.id);if(token!==serial)return;main.innerHTML=`<div class="project-visual-strip"><img src="assets/region-${D.regions.findIndex(r=>r.region===p.region)}.svg" alt=""><span>REGIONAL PROJECT · EVIDENCE RECORD</span><small>개념 일러스트</small></div><div class="project-head"><a class="subtle" href="#projects">← 전체 사업</a><div class="id">${E(p.id)} · ${E(p.category)}</div><h1>${E(p.title)}</h1>${projectConnections(p)}<div class="tags">${pill('원문 기재')}${pill(p.detail_match||'상세 연결 미확인','neutral')}${p.terms.map(t=>`<span class="tag">${E(t)}</span>`).join('')}</div></div>${budgets(p)}<div class="notice">금액·부처·사업 내용은 원자료의 기재값입니다. 실제 소관 확정, 예산 승인, 집행 여부는 별도 확인되지 않았습니다.</div><div class="detail-grid"><div class="card"><h3>요약서 사업 내용</h3>${quote(p.summary_body)}${meta(p.summary_source,p.summary_location)}</div><div class="card"><h3>원문 표기</h3><dl>${[['요약서 부처',p.summary_ministry],['상세서 부처',p.detail_ministry],['기간',p.period],['상세서 기간',p.detail_period],['수행 주체 기재',d.components.owner],['입지 기재',d.components.place]].map(([k,v])=>`<dt>${k}</dt><dd>${E(v||'미확인')}</dd>`).join('')}</dl><div class="actions"><a class="button primary" href="${link(p,'graph')}">연결된 지식그래프 →</a></div></div></div><div class="tabs" role="tablist">${[['evidence','원문 근거 '+d.evidence.length],['public','공개자료 '+d.sources.length],['checks','자료 대조·연도별 금액'],['similar','사업내용 문구 대조 '+d.similar.length]].map(([k,t])=>`<button role="tab" data-tab="${k}">${t}</button>`).join('')}</div><div id="detail-content"></div>`;function tab(k){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===k);b.setAttribute('aria-selected',b.dataset.tab===k)});let box=document.querySelector('#detail-content');if(k==='evidence'){box.innerHTML=`<div class="evidence-controls"><label>원문 항목 검색<input id="ev-search" type="search" placeholder="항목명, 근거 ID, 원문 내용"></label></div><div id="ev-list"></div>`;const draw=()=>{let q=document.querySelector('#ev-search').value.toLowerCase(),es=d.evidence.filter(e=>(e.field+' '+e.evidence_id+' '+e.excerpt).toLowerCase().includes(q));document.querySelector('#ev-list').innerHTML=es.map(evidence).join('')||'<div class="empty">일치하는 근거가 없습니다.</div>'};document.querySelector('#ev-search').oninput=draw;draw()}else if(k==='public'){box.innerHTML=`<div class="notice">${E(p.public_status)}. 검색 발췌와 직접 열람 범위는 자료별로 표시합니다. 관련 문서의 존재가 동일사업·동일재원을 뜻하지 않습니다.</div><details class="card"><summary>검색 범위와 확인 기록</summary>${record(d.search)}</details>`+d.sources.map(s=>publicCard(s,d.public.find(x=>x.source_id===s.source_id)?.relation)).join('');if(!d.sources.length)box.innerHTML+='<div class="empty">설정한 검색 기준 내 연결 자료 미확인</div>'}else if(k==='checks'){box.innerHTML=`<div class="card"><h3>원자료 간 대조 기록</h3>${record(d.checks)}</div><div class="section-head"><h2>연도별 금액 원문</h2></div><div class="notice">연도 행의 일부 합계를 사업 전체 예산으로 해석하지 않습니다. 단위·기간·공란·대시 처리 기록을 함께 확인하세요.</div>`+d.annual.map(a=>`<article class="evidence-card"><h3>${E(a.year_label)} · 원문 단위: ${E(a.unit)}</h3><p class="subtle">아래 환산 금액: 억원 · 원문 행은 원래 단위 유지</p><div class="table-wrap"><table><tr><th>국비</th><th>지방비</th><th>민자</th><th>합계</th></tr><tr>${['national','local','private','total'].map(k=>`<td>${N(a[k])}</td>`).join('')}</tr></table></div>${quote(a.raw_cells)}${meta(a.source,a.location)}<p>${E(a.row_state)} · ${E(a.unknown_reason)} ${E(a.limit)}</p></article>`).join('')}else box.innerHTML=`<div class="notice">문구 유사도와 공통 검출어에 따른 대조입니다. 동일사업·사업 중복·재원 중복 관계는 미확인입니다.</div>`+d.similar.map(s=>{let other=P.get(s.id_a===p.id?s.id_b:s.id_a);return `<article class="compare-card card"><h3><a href="${link(other)}">${E(other.title)} ↗</a></h3><p>${E(other.id)} · 문구 유사도 ${E(s.cosine)}</p><p>공통 검출어: ${E(s.shared_terms)}</p><div class="source-meta">${E(s.source_a)}<br>${E(s.source_b)}</div>${pill('규칙 대조','rule')} <a class="button" href="${link(other)}">상대 사업 원문 보기</a></article>`}).join('')}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));tab('evidence')}
const labels={id:'사업 ID',region:'권역',title:'사업명',summary_title:'요약서 사업명',detail_title:'상세서 사업명',title_comparison:'사업명 대조',period_comparison:'기간 대조',ministry_comparison:'부처 표기 대조',total_comparison:'총액 대조',query:'검색식',searched:'검색일',status:'확인 상태',method:'방법',limit:'확인 범위',source_ids:'연결 출처 ID',error:'검색 오류',selected_reference_count:'선정 참고자료 수',returned_primary_domain_count:'공식 도메인 검색 결과 수'};
Object.assign(labels,{detail_match:'상세서 연결 방식',summary_period:'요약서 기간',detail_period:'상세서 기간',summary_total:'요약서 총액 (억원)',detail_total:'상세서 총액 (억원)',total_delta:'총액 차이 (억원)',total_difference_band:'총액 차이 구간',summary_ministry:'요약서 부처',detail_ministry:'상세서 부처',ministry_source:'부처 표기 근거',placeholder_lines:'임시 표기 행 수',placeholder_source:'임시 표기 근거',summary_location:'요약서 위치',detail_location:'상세서 위치',known_whole:'전체 사업비 숫자 있음 (1/0)',known_window:'기간 투자액 숫자 있음 (1/0)',known_national:'기간 국비 숫자 있음 (1/0)',annual_rows:'연도 행 수',annual_valid_rows:'대조 가능 연도 행 수',annual_years:'기재 연도',annual_partial_total:'확인 연도 부분합 (억원)',annual_partial_national:'확인 연도 국비 부분합 (억원)',annual_national_rows:'국비 기재 연도 행 수',annual_invalid_rows:'대조 제한 연도 행 수',annual_arithmetic_difference_rows:'산술차이 연도 행 수',annual_source:'연도표 근거',annual_limitation:'연도표 확인 범위',tag:'검출 용어',pattern:'검출 규칙',meaning:'의미',scope:'범위'});
Object.assign(labels,{detail_match:'상세서 연결 방식',summary_period:'요약서 기간',detail_period:'상세서 기간',summary_total:'요약서 총액 (억원)',detail_total:'상세서 총액 (억원)',total_delta:'총액 차이 (억원)',total_difference_band:'총액 차이 구간',summary_ministry:'요약서 부처',detail_ministry:'상세서 부처',ministry_source:'부처 표기 근거',placeholder_lines:'임시 표기 행 수',placeholder_source:'임시 표기 근거',summary_location:'요약서 위치',detail_location:'상세서 위치',known_whole:'전체 사업비 숫자 있음 (1/0)',known_window:'기간 투자액 숫자 있음 (1/0)',known_national:'기간 국비 숫자 있음 (1/0)',annual_rows:'연도 행 수',annual_valid_rows:'대조 가능 연도 행 수',annual_years:'기재 연도',annual_partial_total:'확인 연도 부분합 (억원)',annual_partial_national:'확인 연도 국비 부분합 (억원)',annual_national_rows:'국비 기재 연도 행 수',annual_invalid_rows:'대조 제한 연도 행 수',annual_arithmetic_difference_rows:'산술차이 연도 행 수',annual_source:'연도표 근거',annual_limitation:'연도표 확인 범위',tag:'검출 용어',pattern:'검출 규칙',meaning:'의미',scope:'범위'});
function record(obj){return `<dl>${Object.entries(obj).filter(([k,v])=>v!==null&&v!==undefined&&v!=='').map(([k,v])=>`<dt>${E(labels[k]||k)}</dt><dd>${E(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>`}
async function graph(p,token){
 const d=await packet(p.id);if(token!==serial)return;
 const pub=d.sources.filter(s=>d.public.some(c=>c.source_id===s.source_id));
 const groups=[
  {key:'original',title:'원문 근거',count:d.evidence.length,level:'original',description:'사업내용 · 예산 · 기간 · 추진 주체'},
  {key:'public',title:'공개자료',count:pub.length,level:'public',description:'공개 문서와 열람 범위'},
  {key:'record',title:'권역·부처 표기',count:1+p.ministry_terms.length,level:'original',description:'요약서에 기재된 정보'},
  {key:'terms',title:'내용 용어',count:p.terms.length,level:'rule',description:'정의어 검출에 따른 연결'},
  {key:'similar',title:'문구 대조 사업',count:d.similar.length,level:'rule',description:'유사 문구를 가진 사업 연결'}
 ];
 main.innerHTML=heading('지식그래프','사업을 선택하고, 아래의 근거 묶음을 눌러 확인하세요. 원문과 공개자료를 종류별로 정리했습니다.')+`<form id="graph-search" class="graph-controls"><label>사업 찾기<input id="graph-query" list="project-options" placeholder="사업 ID 또는 사업명" value="${E(p.id)}"><datalist id="project-options">${D.projects.map(x=>`<option value="${E(x.id)}">${E(x.title)}</option>`).join('')}</datalist></label><button class="primary">사업 이동</button><a class="button" href="${link(p)}">사업 상세</a></form><div id="graph-message" role="status"></div><div class="actions"><a class="button" href="#explore">권역·부처에서 연결 사업 찾기 →</a></div>${projectConnections(p)}<div class="atlas-toolbar">${levelLegend()}<button id="large-labels" aria-pressed="false">글씨 더 크게</button></div><div class="evidence-atlas"><section class="relationship-map" aria-label="사업과 근거 연결도"><div class="map-caption">선택한 사업 <span>사업 → 근거 묶음 → 원문</span></div><button class="focus-project" id="focus-project" aria-label="선택 사업의 연결 근거 전체 보기"><span class="focus-kicker">${E(p.region)} · ${E(p.category)}</span><strong>${E(p.title)}</strong><span>${E(p.id)} <b>연결 근거 전체 보기 ↓</b></span></button><div class="map-stem" aria-hidden="true"></div><div class="evidence-groups">${groups.map((g,i)=>`<button class="evidence-group ${g.level}" data-group="${g.key}" aria-controls="inspector"><span class="group-number">0${i+1}</span><span class="group-title">${g.title} <b>${g.count}</b></span><span class="group-description">${g.description}</span><span class="group-action">${g.count?'근거 보기 →':'연결 항목 없음'}</span></button>`).join('')}</div><div class="map-note">${d.evidence.length}개 원문 근거와 ${pub.length}개 공개자료를 묶어 표시했습니다. 각 묶음에서 모든 연결 항목을 확인할 수 있습니다.</div><div class="notice amber">공개자료·문구 대조 연결은 동일사업 확정을 뜻하지 않습니다.</div></section><aside class="evidence-reader" id="inspector" aria-label="선택한 사업의 근거" aria-live="polite" tabindex="-1"></aside></div>`;
 document.querySelector('#graph-search').onsubmit=e=>{e.preventDefault();const q=document.querySelector('#graph-query').value.trim();let found=P.get(q)||D.projects.find(x=>x.title===q)||D.projects.find(x=>q&&(x.title+' '+x.id).includes(q));if(found){if(found.id===p.id)show('all');else location.hash=link(found,'graph')}else document.querySelector('#graph-message').textContent='일치하는 사업이 없습니다. 사업명 또는 ID를 확인해 주세요.'};
 const originalRows=()=>d.evidence.map(e=>`<details class="reader-item"><summary><span><strong>${E(e.field)}</strong><small>${E(e.evidence_id)} · ${E(e.location)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body">${pill('원문 기재')}${quote(e.excerpt)}${meta(e.source,e.location)}</div></details>`).join('')||'<p class="reader-empty">연결된 원문 근거가 없습니다.</p>';
 const publicRows=()=>pub.map(s=>`<details class="reader-item"><summary><span><strong>${E(s.title)}</strong><small>${E(s.read_level)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body">${publicCard(s,d.public.find(c=>c.source_id===s.source_id)?.relation)}</div></details>`).join('')||'<p class="reader-empty">설정한 검색 기준 내 연결 공개자료 미확인</p>';
 function content(k){
  if(k==='original')return `<p class="reader-help">항목을 펼치면 원문 인용과 문서·문단 위치가 보입니다.</p>${originalRows()}`;
  if(k==='public')return `<div class="notice">${E(p.public_status)}. 자료별 열람 범위와 동일사업 미확인을 구분합니다.</div>${publicRows()}${d.sources.length>pub.length?`<p class="source-meta">기존 일반 참고자료 ${d.sources.length-pub.length}개는 <a href="${link(p)}">사업 상세의 공개자료 탭</a>에서 확인할 수 있습니다.</p>`:''}`;
  if(k==='record')return `${projectConnections(p)}${pill('원문 기재')}<dl><dt>권역</dt><dd>${E(p.region)}</dd><dt>요약서 부처 표기</dt><dd>${E(p.summary_ministry||'미기재')}</dd><dt>상세서 부처 표기</dt><dd>${E(p.detail_ministry||'미확인')}</dd></dl>${meta(p.summary_source,p.summary_location)}${meta(p.detail_source,p.detail_location)}<div class="notice amber">원문에 적힌 부처입니다. 실제 소관 확정은 미확인입니다.</div>`;
  if(k==='terms')return `<p class="reader-help">정의어 검출에 따른 연결입니다. 실제 수행 여부·독립 내역사업 여부는 미확인입니다.</p><div class="tags">${p.terms.map(t=>`<span class="tag">${E(t)}</span>`).join('')||'정의어 미검출'}</div><h3 class="reader-subtitle">용어 대조에 사용한 원문</h3>${d.evidence.filter(e=>String(p.detail_content_evidence||p.summary_evidence).includes(e.evidence_id)).map(evidence).join('')}`;
  return `<div class="notice amber">문구 대조 결과입니다. 동일사업·중복재원 관계는 미확인입니다.</div>${d.similar.map(s=>{const other=P.get(s.id_a===p.id?s.id_b:s.id_a);return `<details class="reader-item"><summary><span><strong>${E(other.title)}</strong><small>${E(other.id)} · 문구 유사도 ${E(s.cosine)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body"><p>공통 검출어: ${E(s.shared_terms)}</p>${meta(s.source_a,s.source_b)}<div class="actions"><a class="button primary" href="${link(other,'graph')}">이 사업의 연결 근거 →</a><a class="button" href="${link(other)}">사업 원문 보기</a></div></div></details>`}).join('')||'<p class="reader-empty">해당 규칙으로 연결된 문구 대조 사업이 없습니다.</p>'}`;
 }
 function show(k,focus=false){
  const box=document.querySelector('#inspector');const g=groups.find(x=>x.key===k);
  document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',b.dataset.group===k);b.setAttribute('aria-pressed',String(b.dataset.group===k))});
  document.querySelector('#focus-project').classList.toggle('active',k==='all');
  box.innerHTML=`<div class="reader-header"><span class="eyebrow">CONNECTED EVIDENCE</span>${k!=='all'?'<button class="link-button" id="reader-back">← 전체 근거</button>':''}<h2>${k==='all'?'연결 근거 한눈에 보기':g.title+' <span class="muted">'+g.count+'</span>'}</h2><p class="reader-project-title">${E(p.title)}</p></div>`+(k==='all'?`<div class="reader-totals"><button data-read="original"><b>${d.evidence.length}</b><span>원문 근거</span></button><button data-read="public"><b>${pub.length}</b><span>공개자료</span></button></div><div class="reader-status"><strong>확인 수준</strong><p>${pill('원문 기재')} ${E(p.detail_match||'상세 연결 미확인')}</p><p>${pill('공개자료','public')} ${E(p.public_status)}</p><p>${pill('미확인','unknown')} 실제 소관·동일사업·재원 관계</p></div><h3 class="reader-subtitle">원문 근거 <small>${d.evidence.length}개 · 항목을 눌러 펼치기</small></h3>${originalRows()}<h3 class="reader-subtitle">공개자료 <small>${pub.length}개</small></h3>${publicRows()}<a class="button reader-detail-link" href="${link(p)}">사업의 전체 분석표 보기 →</a>`:content(k));
  box.scrollTop=0;
  document.querySelector('#reader-back')?.addEventListener('click',()=>show('all'));
  box.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>show(b.dataset.read));
  if(focus&&matchMedia('(max-width:1000px)').matches){box.scrollIntoView({behavior:'smooth',block:'start'});box.focus({preventScroll:true})}
 }
 document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>show(b.dataset.group,true));
 document.querySelector('#focus-project').onclick=()=>show('all',true);
 document.querySelector('#large-labels').onclick=e=>{const on=document.querySelector('.evidence-atlas').classList.toggle('larger-type');e.currentTarget.setAttribute('aria-pressed',on);e.currentTarget.textContent=on?'기본 글씨 크기':'글씨 더 크게'};
 show('all');
}

async function sourcePage(token){const ds=await sources();if(token!==serial)return;main.innerHTML=heading('근거 자료실','공개 참고자료 전체를 검색합니다. 사업별 원문 문단·표 위치는 사업 상세의 ‘원문 근거’에서 확인할 수 있습니다.')+`<div class="actions"><a class="button" href="#projects">사업별 원문 근거 찾기 →</a></div><label>공개자료 검색<input type="search" id="source-q" placeholder="문서명, 출처 ID, 발행 도메인"></label><div id="source-results"></div>`;let page=1;function draw(){const q=document.querySelector('#source-q').value.toLowerCase(),rows=ds.sources.filter(s=>(s.title+' '+s.source_id+' '+s.publisher_domain).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);document.querySelector('#source-results').innerHTML=`<div class="result-heading"><h2>${N(rows.length)}개 자료</h2><small>기존 일반 참고자료 89개 포함</small></div>`+rows.slice((page-1)*12,page*12).map(s=>publicCard(s)+`<div class="tags">${(ds.refs[s.source_id]||[]).map(id=>`<a class="tag" href="${link(P.get(id))}">${E(id)} ↗</a>`).join('')}</div>`).join('')+`<div class="pagination"><button id="sprev" ${page===1?'disabled':''}>이전</button>${page} / ${pages}<button id="snext" ${page===pages?'disabled':''}>다음</button></div>`;document.querySelector('#sprev').onclick=()=>{page--;draw()};document.querySelector('#snext').onclick=()=>{page++;draw()}}document.querySelector('#source-q').oninput=()=>{page=1;draw()};draw()}
function method(){main.innerHTML=heading('확인 수준·분석 기준','데이터에 있는 사실, 대조 규칙으로 얻은 연결, 확인하지 못한 관계를 구분합니다.')+`<div class="card">${levelLegend()}<dl><dt>원문 기재</dt><dd>요약서·상세서에 적힌 내용과 문서·문단·표 위치입니다. 계획의 승인·집행을 확인한 것은 아닙니다.</dd><dt>공개자료</dt><dd>공개 문서에서 확인된 제목·검색 발췌·직접 열람 범위입니다. 대부분 검색 발췌 수준이며 자료별 열람 수준을 표시합니다.</dd><dt>규칙 대조</dt><dd>정의어 검출과 문구 유사도에 따른 연결입니다. 동일사업·독립 내역사업·중복재원 관계를 확정하지 않습니다.</dd><dt>미확인</dt><dd>누락·연결 제한·보류·검증되지 않은 관계입니다. 미확인을 0 또는 ‘없음’으로 바꾸지 않습니다.</dd></dl></div><div class="section-head"><h2>분석 범위</h2></div><div class="card"><p>전체 1,312건, 원문 근거 19,731개, 연도 행 6,507개, 공개자료 1,773개를 수록합니다. 상세서 연결이 없는 19건과 제목만 연결된 8건은 원래 확인 상태를 유지합니다.</p><p>사업명 문자열 확인 31건, 관련어 문서 확인 800건, 설정한 검색·대조 기준 내 미확인 481건입니다. 앞의 두 분류도 동일사업 여부는 미확인입니다.</p><p>사업내용 문구 대조는 전체 860,016쌍에서 권역 내·권역 간 사업별 상위 3개, 유사도 0.15 이상을 합친 1,934쌍입니다. 그래프에서 선택적으로 표시합니다.</p><p>부처는 원문 표기를 유지합니다. 부처 변경 의견·전문가 판단·정책 제안은 이 열람 데이터에 포함하지 않았습니다.</p></div><div class="section-head"><h2>내용 용어 검출 규칙</h2></div>${D.rules.map(r=>`<details class="card"><summary>${E(r.tag)}</summary>${record(r)}</details>`).join('')}`}
function downloads(){main.innerHTML=heading('자료 내려받기','동일한 데이터로 분석표와 연결 관계를 확인할 수 있습니다.')+`<div class="download-grid">${[['project-analysis.xlsx','전체 분석 엑셀','전체 사업, 근거, 대조표, 검색 기록과 확인 상태'],['project-catalog.json','사업 목록 데이터','전체 1,312개 사업의 사실 기재값'],['knowledge-graph.json','지식그래프 데이터',N(D.meta.graphNodes)+'개 노드 · '+N(D.meta.graphEdges)+'개 연결 · 출처와 확인 수준']].map(([f,t,s])=>`<a class="download-card card" href="downloads/${f}" download><div class="download-icon">↓</div><h2>${t}</h2><p>${s}</p><span class="pill neutral">${f.split('.').pop().toUpperCase()}</span></a>`).join('')}</div><div class="notice">2026.10.30 분석 스냅샷입니다. 이후 변경된 사업·기관·예산 정보는 자동 반영되지 않습니다.</div>`}
const ministryRows=window.MINISTRY_INDEX;
const hubLink=(kind,name='',source='all')=>'#explore?'+new URLSearchParams({kind,name,source}).toString();
function projectConnections(p){const rows=ministryRows.filter(r=>r.id===p.id);return `<div class="connection-chips"><a href="${hubLink('region',p.region)}">${E(p.region)} · 연결 사업 ↗</a>${[...new Set(rows.map(r=>r.label))].map(label=>`<a href="${hubLink('ministry',label)}">${E(label)} <small>${[...new Set(rows.filter(r=>r.label===label).map(r=>r.origin==='summary'?'요약서':'상세서'))].join('·')}</small> ↗</a>`).join('')}</div>`}
function explore(params){
 const kind=params.get('kind')==='ministry'?'ministry':'region',name=params.get('name')||'',source=['summary','detail'].includes(params.get('source'))?params.get('source'):'all';
 const entries=ministryRows.filter(r=>source==='all'||r.origin===source),names=kind==='region'?D.regions.map(r=>r.region):[...new Set(entries.map(r=>r.label))].sort((a,b)=>a.localeCompare(b,'ko'));
 const ids=kind==='region'?new Set(D.projects.filter(p=>!name||p.region===name).map(p=>p.id)):new Set(entries.filter(r=>!name||r.label===name).map(r=>r.id));
 const connected=D.projects.filter(p=>ids.has(p.id));
 main.innerHTML=heading('권역·부처별 연결 사업','권역이나 원문에 기재된 부처를 선택하고, 사업 카드를 눌러 연결된 원문 근거를 확인하세요.')+`<div class="actions"><a class="button" href="#compare?kind=${kind}">사업 수·예산 비교 →</a><a class="button" href="#multiple">복수 부처 연결 보기 →</a></div><div class="hub-switch"><a class="button ${kind==='region'?'primary':''}" href="${hubLink('region')}">권역으로 보기</a><a class="button ${kind==='ministry'?'primary':''}" href="${hubLink('ministry')}">원문 부처로 보기</a></div><div class="notice">부처는 요약서·상세서의 부처 항목에서 이름이 직접 확인된 경우만 연결합니다. 약칭과 정식 명칭을 합치거나 실제 소관을 추정하지 않습니다. 같은 사업이 여러 부처에 연결될 수 있습니다.</div>${kind==='ministry'?`<label class="hub-source">기재 문서<select id="hub-source"><option value="all" ${source==='all'?'selected':''}>요약서 또는 상세서</option><option value="summary" ${source==='summary'?'selected':''}>요약서 기재만</option><option value="detail" ${source==='detail'?'selected':''}>상세서 기재만</option></select></label>`:''}<div class="hub-layout"><aside class="hub-picker"><h2>${kind==='region'?'권역':'원문 부처 표기'}</h2><label>목록에서 찾기<input id="hub-name-query" type="search" placeholder="${kind==='region'?'권역':'부처 표기'} 검색"></label><div id="hub-names">${names.map(n=>{const count=kind==='region'?D.regions.find(r=>r.region===n).count:new Set(entries.filter(r=>r.label===n).map(r=>r.id)).size;return `<a data-hub-name="${E(n)}" class="${name===n?'active':''}" href="${hubLink(kind,n,source)}"><span>${E(n)}</span><b>${N(count)}</b></a>`}).join('')}</div><p id="hub-name-empty" hidden>일치하는 표기가 없습니다.</p></aside><section class="hub-projects"><div class="hub-selected"><span class="eyebrow">${kind==='region'?'REGION':'ORIGINAL MINISTRY RECORD'}</span><h2>${E(name||(kind==='region'?'전체 권역':'원문 부처 기재 사업'))} <span>${N(connected.length)}개 사업</span></h2><p>${name?'선택 항목 → 연결 사업 → 원문 근거':'왼쪽 목록에서 권역이나 부처를 선택하세요.'}</p></div><div class="hub-project-controls"><label>연결 사업 검색<input id="hub-project-query" type="search" placeholder="사업명 또는 사업 ID"></label><label>권역<select id="hub-region"><option value="">전체 권역</option>${D.regions.filter(r=>connected.some(p=>p.region===r.region)).map(r=>`<option>${E(r.region)}</option>`).join('')}</select></label></div><div id="hub-results"></div></section></div>`;
 document.querySelector('#hub-source')?.addEventListener('change',e=>location.hash=hubLink(kind,name,e.target.value));
 document.querySelector('#hub-name-query').oninput=e=>{let visible=0;document.querySelectorAll('[data-hub-name]').forEach(el=>{el.hidden=!el.dataset.hubName.includes(e.target.value.trim());if(!el.hidden)visible++});document.querySelector('#hub-name-empty').hidden=visible>0};
 let page=1;
 function draw(){const q=document.querySelector('#hub-project-query').value.trim().toLowerCase(),reg=document.querySelector('#hub-region').value,rows=connected.filter(p=>(!reg||p.region===reg)&&(!q||(p.title+' '+p.id).toLowerCase().includes(q))),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);
 document.querySelector('#hub-results').innerHTML=`<div class="result-heading"><strong>${N(rows.length)}개 사업</strong><small>사업을 누르면 원문 근거로 이동</small></div><div class="hub-card-grid">${rows.slice((page-1)*12,page*12).map(p=>{const origins=kind==='ministry'?entries.filter(r=>r.id===p.id&&(!name||r.label===name)):[];return `<a class="hub-project-card" href="${link(p,'graph')}"><div class="hub-card-meta">${E(p.region)} · ${E(p.category)}<span>${p.source_count}개 원문 근거</span></div><h3>${E(p.title)}</h3><small>${E(p.id)}</small><div class="hub-raw"><span>요약서 부처 표기</span><p>${E(p.summary_ministry||'미기재')}</p>${kind==='ministry'?`<span>연결 근거</span>${origins.map(r=>`<p><b>${r.origin==='summary'?'요약서':'상세서'}</b> ${E(r.raw)}</p><small>${E(r.source)} · ${E(r.location)}</small>`).join('')}`:''}</div><div class="hub-card-footer"><span>${E(p.detail_match||'상세 연결 미확인')}</span><strong>원문 근거 보기 →</strong></div></a>`}).join('')}</div>${rows.length?'':'<div class="empty">조건에 맞는 연결 사업이 없습니다.</div>'}<div class="pagination"><button id="hub-prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages}</span><button id="hub-next" ${page===pages?'disabled':''}>다음 →</button></div>`;
 document.querySelector('#hub-prev').onclick=()=>{page--;draw()};document.querySelector('#hub-next').onclick=()=>{page++;draw()};}
 document.querySelector('#hub-project-query').oninput=()=>{page=1;draw()};document.querySelector('#hub-region').onchange=()=>{page=1;draw()};draw();
}

const budgetFields=[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']];
function budgetAggregate(ps,k){const a={sum:0,count:0,original:0,provisional:0,held:0,unknown:0};for(const p of ps){if(p[k+'_status']==='보류')a.held++;else if(p[k]===null||p[k]===undefined)a.unknown++;if(p[k]!==null&&p[k]!==undefined&&p[k+'_status']!=='보류'){a.sum+=p[k];a.count++;if(p[k+'_status']==='잠정채택')a.provisional++;else a.original++}}return a}
function budgetCompare(params){
 const kind=params.get('kind')==='ministry'?'ministry':'region';
 main.innerHTML=heading('사업 수·예산 비교','권역별·원문 부처별로 사업 수와 세 가지 예산을 비교합니다. 금액이 없는 항목은 합계에서 제외하고 별도 표시합니다.')+`<div class="actions"><a class="button" href="#multiple">복수 부처 연결·반복 집계 보기 →</a></div><div class="hub-switch"><a class="button ${kind==='region'?'primary':''}" href="#compare?kind=region">권역별 비교</a><a class="button ${kind==='ministry'?'primary':''}" href="#compare?kind=ministry">원문 부처별 비교</a></div><div class="notice">단위: 억원 · 철도 포함 전체 사업 기준. 표시 금액은 숫자가 있는 항목의 부분합이며 확정 예산이 아닙니다. ‘잠정채택’은 기존 데이터 상태를 유지한 것입니다. 보류·미확인 금액은 0으로 처리하지 않습니다.${kind==='ministry'?'<br><strong>부처 표기는 원문 기준입니다. 한 사업이 여러 부처에 연결될 수 있으므로 부처별 금액을 더하면 중복됩니다.</strong>':''}</div><div class="budget-filters"><label>${kind==='region'?'권역':'부처 표기'} 찾기<input id="compare-query" type="search" placeholder="이름 검색"></label>${kind==='ministry'?'<label>기재 문서<select id="compare-source"><option value="all">요약서 또는 상세서</option><option value="summary">요약서 기재만</option><option value="detail">상세서 기재만</option></select></label>':''}<label>비교·정렬 기준<select id="compare-metric"><option value="count">사업 수</option>${budgetFields.map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></label><label>정렬<select id="compare-order"><option value="desc">큰 순서</option><option value="asc">작은 순서</option></select></label></div><div id="comparison-output"></div><section id="held-detail" aria-live="polite" tabindex="-1"></section>`;
 let displayed=[];
 function draw(){const q=document.querySelector('#compare-query').value.trim(),source=document.querySelector('#compare-source')?.value||'all',metric=document.querySelector('#compare-metric').value,order=document.querySelector('#compare-order').value;
 const entries=ministryRows.filter(r=>source==='all'||r.origin===source),names=kind==='region'?D.regions.map(r=>r.region):[...new Set(entries.map(r=>r.label))];
 displayed=names.filter(n=>!q||n.includes(q)).map(name=>{const ids=kind==='region'?new Set(D.projects.filter(p=>p.region===name).map(p=>p.id)):new Set(entries.filter(r=>r.label===name).map(r=>r.id));const ps=D.projects.filter(p=>ids.has(p.id));return {name,ps,count:ps.length,...Object.fromEntries(budgetFields.map(([k])=>[k,budgetAggregate(ps,k)]))}});
 const val=r=>metric==='count'?r.count:r[metric].count?r[metric].sum:null;
 displayed.sort((a,b)=>{const x=val(a),y=val(b);if(x===null)return y===null?0:1;if(y===null)return -1;return (order==='desc'?y-x:x-y)||a.name.localeCompare(b.name,'ko')});
 const union=new Set(displayed.flatMap(r=>r.ps.map(p=>p.id))),ps=D.projects.filter(p=>union.has(p.id)),chart=displayed.slice(0,12),max=Math.max(1,...chart.map(r=>val(r)||0));
 const cell=(a,index,k)=>`<strong>${a.count?N(a.sum):'미확인'}</strong><span class="count-note">숫자 있음 ${N(a.count)}건 · 부분합</span><span class="count-note">원문이관 ${N(a.original)} · 잠정채택 ${N(a.provisional)}</span><button class="budget-held ${a.held+a.unknown?'has-missing':''}" data-held="${index}" data-field="${k}">보류 ${N(a.held)}건 · 기타 미확인 ${N(a.unknown)}건${a.held+a.unknown?' ↗':''}</button>`;
 document.querySelector('#comparison-output').innerHTML=`<div class="section-head"><h2>현재 목록에 연결된 고유 사업 <span class="muted">${N(ps.length)}건</span></h2><small>${displayed.length}개 ${kind==='region'?'권역':'부처 표기'} · 사업 ID 중복 제거</small></div><div class="budgets">${budgetFields.map(([k,t])=>{const a=budgetAggregate(ps,k);return `<div class="budget-card"><div class="label">${t} · 기재 금액 부분합</div><strong>${a.count?N(a.sum):'미확인'} <span class="unit">${a.count?'억원':''}</span></strong><p class="budget-coverage">숫자 있음 ${a.count}건 / ${ps.length}건</p><span class="pill unknown">보류 ${a.held}건 · 기타 미확인 ${a.unknown}건</span></div>`}).join('')}</div><div class="card compare-chart"><div class="section-head"><h2>${metric==='count'?'사업 수':budgetFields.find(([k])=>k===metric)[1]} 비교</h2><small>${displayed.length>12?'현재 정렬 앞 12개 · 전체는 아래 표':'전체 목록'} · ${metric==='count'?'건':'억원'}</small></div>${chart.map(r=>`<a class="compare-bar" href="${hubLink(kind,r.name,source)}"><span class="compare-name">${E(r.name)}</span><span class="compare-track"><i style="width:${val(r)===null?0:Math.max(0,val(r)/max*100)}%"></i></span><strong>${val(r)===null?'미확인':N(val(r))}</strong></a>`).join('')||'<p class="empty">일치하는 항목이 없습니다.</p>'}</div><div class="section-head"><h2>사업 수·예산 상세 비교</h2><small>이름 → 사업 목록 · 보류 건수 → 해당 사업</small></div><div class="card table-wrap budget-comparison"><table><thead><tr><th>${kind==='region'?'권역':'원문 부처 표기'}</th><th class="num">사업 수</th>${budgetFields.map(([,t])=>`<th class="num">${t}<small>억원</small></th>`).join('')}</tr></thead><tbody>${displayed.map((r,i)=>`<tr><th scope="row"><a href="${hubLink(kind,r.name,source)}">${E(r.name)} ↗</a></th><td class="num">${N(r.count)}</td>${budgetFields.map(([k])=>`<td class="num">${cell(r[k],i,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice amber">‘보류’는 해당 금액을 정하지 못해 합계에서 제외한 상태입니다. 현재 데이터의 보류 항목은 모두 집계 금액이 비어 있습니다. ‘기타 미확인’은 보류 표기 없이 금액이 비어 있는 항목이며, 보류와 중복 집계하지 않습니다. 미확인 금액의 합계 자체는 산출할 수 없습니다.</div>`;
 document.querySelector('#held-detail').innerHTML='';document.querySelectorAll('[data-held]').forEach(b=>b.onclick=()=>held(Number(b.dataset.held),b.dataset.field));
 }
 function held(i,k){const r=displayed[i],rows=r.ps.filter(p=>p[k+'_status']==='보류'||p[k]===null||p[k]===undefined),field=budgetFields.find(([key])=>key===k)[1];let page=1;function render(){const pages=Math.max(1,Math.ceil(rows.length/15));const box=document.querySelector('#held-detail');box.innerHTML=`<div class="section-head"><h2>${E(r.name)} · ${field}</h2><button id="held-close">닫기</button></div><div class="notice">보류·미확인 ${rows.length}건. 금액을 0으로 치환하지 않습니다. 사업을 선택하면 원문에 적힌 예산과 확인 범위를 볼 수 있습니다.</div><div class="card table-wrap"><table><thead><tr><th>사업</th><th>상태</th><th>집계 금액</th><th>근거</th></tr></thead><tbody>${rows.slice((page-1)*15,page*15).map(p=>`<tr><td><span class="id">${E(p.id)}</span><a href="${link(p,'graph')}">${E(p.title)}</a></td><td>${pill(p[k+'_status']==='보류'?'보류':'미확인','unknown')}</td><td>미확인 · 합계 제외</td><td><a class="button" href="${link(p,'graph')}">원문 예산 보기</a></td></tr>`).join('')||'<tr><td colspan="4">보류·미확인 항목이 없습니다.</td></tr>'}</tbody></table></div><div class="pagination"><button id="held-prev" ${page===1?'disabled':''}>이전</button>${page} / ${pages}<button id="held-next" ${page===pages?'disabled':''}>다음</button></div>`;document.querySelector('#held-close').onclick=()=>box.innerHTML='';document.querySelector('#held-prev').onclick=()=>{page--;render()};document.querySelector('#held-next').onclick=()=>{page++;render()};}render();document.querySelector('#held-detail').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#held-detail').focus({preventScroll:true})}
 document.querySelector('#compare-query').oninput=draw;['compare-source','compare-metric','compare-order'].forEach(id=>{const el=document.getElementById(id);if(el)el.onchange=draw});draw();
}

function multipleMinistryProjects(projects,records,source='all'){
 const byId=new Map();for(const r of records){if(source!=='all'&&r.origin!==source)continue;if(!byId.has(r.id))byId.set(r.id,[]);byId.get(r.id).push(r)}
 return projects.map(p=>{const rs=byId.get(p.id)||[],labels=[...new Set(rs.map(r=>r.label))],together=['summary','detail'].some(origin=>new Set(rs.filter(r=>r.origin===origin).map(r=>r.label)).size>1);return {p,records:rs,labels,m:labels.length,together}}).filter(r=>r.m>1);
}
function multipleMinistryTotals(rows){
 const out={unique:rows.length,repeated:rows.reduce((s,r)=>s+r.m,0)};out.extra=out.repeated-out.unique;
 for(const k of ['whole','window','national']){const a={unique:0,repeated:0,extra:0,known:0,held:0,unknown:0,heldRepeated:0,unknownRepeated:0,provisional:0};for(const r of rows){const p=r.p;if(p[k+'_status']==='보류'){a.held++;a.heldRepeated+=r.m}else if(p[k]===null||p[k]===undefined){a.unknown++;a.unknownRepeated+=r.m}else{a.known++;a.unique+=p[k];a.repeated+=p[k]*r.m;a.extra+=p[k]*(r.m-1);if(p[k+'_status']==='잠정채택')a.provisional++}}out[k]=a}return out;
}
function multiMinistry(params){
 const requestedSource=['summary','detail'].includes(params.get('source'))?params.get('source'):'all';
 main.innerHTML=heading('여러 부처 표기에 연결된 사업','연결된 부처의 원문 표기와 근거를 살펴보고, 부처별 합산에서 반복되는 사업 수와 금액을 확인합니다.')+`<div class="notice">이 화면의 ‘부처’는 <strong>원문 부처 표기</strong> 기준입니다. 약칭·정식 명칭은 합치지 않습니다. 실제로 서로 다른 부처인지, 공동 주관인지 또는 예산이 중복 편성됐는지를 확정한 결과는 아닙니다.</div><div class="budget-filters"><label>기재 문서<select id="multi-source"><option value="all" ${requestedSource==='all'?'selected':''}>요약서 또는 상세서</option><option value="summary" ${requestedSource==='summary'?'selected':''}>요약서 기재만</option><option value="detail" ${requestedSource==='detail'?'selected':''}>상세서 기재만</option></select></label><label>연결 형태<select id="multi-type"><option value="all">전체 복수 표기 연결</option><option value="together">한 문서에 복수 표기</option><option value="across">문서 간 다른 표기만</option></select></label><label>권역<select id="multi-region"><option value="">전체 권역</option>${D.regions.map(r=>`<option>${E(r.region)}</option>`).join('')}</select></label><label>사업·부처 검색<input id="multi-query" type="search" placeholder="사업명, ID, 원문 부처 표기"></label></div><div id="multi-summary"></div><div class="result-heading"><h2>연결 사업과 원문 근거</h2><label>정렬<select id="multi-sort"><option value="m">연결 표기 많은 순</option><option value="whole">전체 사업비 큰 순</option><option value="window">기간 투자액 큰 순</option><option value="national">국비 요구액 큰 순</option></select></label></div><div id="multi-projects"></div>`;
 let rows=[],page=1;
 function draw(){const source=document.querySelector('#multi-source').value,type=document.querySelector('#multi-type').value,region=document.querySelector('#multi-region').value,q=document.querySelector('#multi-query').value.trim().toLowerCase();
 const all=multipleMinistryProjects(D.projects,ministryRows,source);rows=all.filter(r=>(type==='all'||(type==='together'?r.together:!r.together))&&(!region||r.p.region===region)&&(!q||(r.p.title+' '+r.p.id+' '+r.labels.join(' ')).toLowerCase().includes(q)));
 const t=multipleMinistryTotals(rows),together=rows.filter(r=>r.together).length;
 document.querySelector('#multi-summary').innerHTML=`<div class="multi-scope"><strong>현재 조건에 맞는 ${N(t.unique)}개 고유 사업</strong><span>한 문서에 복수 표기 ${N(together)}건 · 문서 간 다른 표기만 ${N(t.unique-together)}건</span></div><div class="metrics multi-metrics"><div class="metric"><div class="label">고유 사업 수 · 사업당 1회</div><strong>${N(t.unique)}</strong><small>건</small></div><div class="metric"><div class="label">부처 표기별 합산 건수</div><strong>${N(t.repeated)}</strong><small>건</small></div><div class="metric"><div class="label">추가로 반복 집계되는 건수</div><strong>${N(t.extra)}</strong><small>건</small></div></div><div class="card table-wrap multi-totals"><table><thead><tr><th>예산 구분 · 억원</th><th class="num">사업당 한 번<br>기재 금액 부분합</th><th class="num">부처 표기별 반복 합산</th><th class="num">반복분 차이</th></tr></thead><tbody>${budgetFields.map(([k,label])=>{const a=t[k];return `<tr><th scope="row">${label}<span class="count-note">숫자 있음 ${a.known}건 · 잠정채택 포함 ${a.provisional}건</span></th><td class="num"><strong>${a.known?N(a.unique):'미확인'}</strong><span class="count-note">보류 ${a.held} · 기타 미확인 ${a.unknown}건 제외</span></td><td class="num"><strong>${a.known?N(a.repeated):'미확인'}</strong><span class="count-note">보류 ${a.heldRepeated} · 기타 미확인 ${a.unknownRepeated}회 제외</span></td><td class="num"><strong class="repeat-amount">${a.known?N(a.extra):'미확인'}</strong><span class="count-note">추가 제외: 보류 ${a.heldRepeated-a.held} · 미확인 ${a.unknownRepeated-a.unknown}회</span></td></tr>`}).join('')}</tbody></table></div><div class="notice amber">반복분 = 각 사업의 기재 금액 × (서로 다른 부처 표기 수 − 1). 동일한 표기가 요약서·상세서에 반복돼도 1개로 셉니다. 위 금액은 <strong>현재 목록의 사업들이 연결된 모든 부처 표기</strong>를 합산한 값이며, 신규 예산이나 실제 재원 중복액이 아닙니다. 보류·미확인 금액은 합산하지 않습니다.</div><details class="card multi-definition"><summary>문서 간 표기 차이는 어떻게 읽나요?</summary><p>예를 들어 요약서에 ‘산업부’, 상세서에 ‘산업통상부’만 기재된 사업은 ‘문서 간 다른 표기만’으로 표시합니다. 두 이름이 서로 다른 실제 부처라는 의미는 아닙니다. 한 문서 안에 여러 표기가 있어도 공동 주관 여부는 원문 표현을 확인해야 합니다.</p><p>상세서 연결 방식과 문단 위치는 각 사업에서 그대로 표시합니다. ‘제목만 연결’ 등 제한이 있는 경우도 해당 상태를 유지합니다.</p></details>`;
 page=1;drawProjects();
 }
 function drawProjects(){const sort=document.querySelector('#multi-sort').value;rows.sort((a,b)=>sort==='m'?b.m-a.m||a.p.id.localeCompare(b.p.id,'ko'):(b.p[sort]??-Infinity)-(a.p[sort]??-Infinity));const pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages);
 document.querySelector('#multi-projects').innerHTML=rows.slice((page-1)*10,page*10).map(r=>{const p=r.p;return `<article class="card multi-project"><div class="multi-project-head"><div><small>${E(p.id)} · ${E(p.region)}</small><h3><a href="${link(p,'graph')}">${E(p.title)} ↗</a></h3></div>${pill(r.together?'한 문서에 복수 표기':'문서 간 다른 표기만',r.together?'original':'unknown')}</div><div class="connection-chips">${r.labels.map(label=>`<a href="${hubLink('ministry',label,document.querySelector('#multi-source').value)}">${E(label)} <small>${[...new Set(r.records.filter(x=>x.label===label).map(x=>x.origin==='summary'?'요약서':'상세서'))].join('·')}</small> ↗</a>`).join('')}</div><p class="multi-count">${r.m}개 원문 부처 표기에 연결 · 사업당 1회 → 부처 표기별 ${r.m}회 · 추가 반복 ${r.m-1}회</p><div class="table-wrap"><table><thead><tr><th>예산 구분</th><th class="num">사업당 1회</th><th class="num">부처 표기별 ${r.m}회</th><th class="num">반복분 차이</th></tr></thead><tbody>${budgetFields.map(([k,label])=>{const known=p[k]!=null&&p[k+'_status']!=='보류';return `<tr><th>${label}<small class="count-note">${E(p[k+'_status']||'미확인')}</small></th><td class="num">${known?N(p[k]):'미확인'}</td><td class="num">${known?N(p[k]*r.m):'합계 제외'}</td><td class="num">${known?N(p[k]*(r.m-1)):'합계 제외'}</td></tr>`}).join('')}</tbody></table></div><details class="multi-original"><summary>부처 원문 표기와 문서 근거 펼치기</summary>${['summary','detail'].filter(origin=>r.records.some(x=>x.origin===origin)).map(origin=>{const x=r.records.find(x=>x.origin===origin);return `<section><h4>${origin==='summary'?'요약서':'상세서'} 부처 항목</h4>${quote(x.raw)}${meta(x.source,x.location)}${origin==='detail'?`<p class="source-meta">상세 연결: ${E(p.detail_match)} · 근거 ID: ${E(x.evidence||'미기재')}</p>`:''}</section>`}).join('')}<a class="button" href="${link(p,'graph')}">사업의 전체 원문 근거 보기 →</a></details></article>`}).join('')||'<div class="empty">조건에 맞는 복수 부처 표기 연결 사업이 없습니다.</div>';
 document.querySelector('#multi-projects').insertAdjacentHTML('beforeend',`<div class="pagination"><button id="multi-prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages} · ${N(rows.length)}개 사업</span><button id="multi-next" ${page===pages?'disabled':''}>다음 →</button></div>`);
 document.querySelector('#multi-prev').onclick=()=>{page--;drawProjects()};document.querySelector('#multi-next').onclick=()=>{page++;drawProjects()};
 }
 ['multi-source','multi-type','multi-region'].forEach(id=>document.getElementById(id).onchange=draw);document.querySelector('#multi-query').oninput=draw;document.querySelector('#multi-sort').onchange=()=>{page=1;drawProjects()};draw();
}

// All summaries use selected unique IDs and literal source ministry labels.
function selectionSummarySheets(projects,records){
 const ps=[...new Map(projects.map(p=>[p.id,p])).values()],labels=new Map(ps.map(p=>[p.id,new Set()]));
 records.forEach(r=>{if(labels.has(r.id)&&r.label)labels.get(r.id).add(r.label)});
 const metrics=[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']];
 const headers=['집계 구분','사업 수 (건·중복 포함 시 회)','예산 항목','집계 가능 금액 (억원·부분합)','금액 포함 건수','잠정채택 건수 (금액 포함 중)','보류 건수 (금액 제외)','기타 미확인 건수 (금액 제외)','집계 기준'];
 function rows(name,items,note){return metrics.map(([key,title])=>{let sum=0,known=0,provisional=0,held=0,unknown=0;for(const p of items){const status=String(p[key+'_status']||'');if(status.includes('보류'))held++;else if(typeof p[key]==='number'&&Number.isFinite(p[key])){known++;sum+=p[key];if(status.includes('잠정'))provisional++}else unknown++}return [name,items.length,title,known?sum:null,known,provisional,held,unknown,note]})}
 const linked=ps.filter(p=>labels.get(p.id).size),unlinked=ps.filter(p=>!labels.get(p.id).size),repeat=linked.flatMap(p=>Array(labels.get(p.id).size).fill(p)),extra=linked.flatMap(p=>Array(labels.get(p.id).size-1).fill(p));
 const make=(name,r)=>({name,headers,widths:[34,24,29,28,19,27,25,30,85],rows:r});
 const overall=make('선택요약',[
  ...rows('선택 전체 · 중복 제거',ps,'사업 ID당 1건. 부처 연결이 없는 사업도 포함.'),
  ...rows('부처 연결 있음 · 중복 제거',linked,'원문 부처 표기가 1개 이상 연결된 사업 ID당 1건.'),
  ...rows('부처 연결 없음 · 중복 제거',unlinked,'부처별 합계에 들어가지 않는 선택 사업. 소관부처가 없다는 뜻은 아님.'),
  ...rows('부처별 반복 합계',repeat,'사업별 서로 다른 원문 부처 표기 수만큼 반복. 동일 표기의 요약서·상세서 중복은 제거.'),
  ...rows('추가 반복분',extra,'부처별 반복 합계 − 부처 연결 있음 중복 제거 합계. 실제 중복 재원 또는 추가 예산이 아님.')
 ]);
 const regionNames=[...new Set(ps.map(p=>p.region||'권역 미기재'))].sort((a,b)=>a.localeCompare(b,'ko'));
 const ministryNames=[...new Set([...labels.values()].flatMap(s=>[...s]))].sort((a,b)=>a.localeCompare(b,'ko'));
 return [overall,make('권역별요약',regionNames.flatMap(name=>rows(name,ps.filter(p=>(p.region||'권역 미기재')===name),'권역 내 사업 ID당 1건. 권역 간 합계는 선택 전체 중복 제거 합계와 일치.'))),make('부처별요약',ministryNames.flatMap(name=>rows(name,ps.filter(p=>labels.get(p.id).has(name)),'요약서·상세서 원문 표기 기준. 부처 내 ID 중복 제거, 부처 간 반복 포함. 약칭·정식 명칭 통합 안 함.')))];
}

let selectedSummaryGroup='region',selectedSummaryFilter=null;
function selectedSummaryTable(sheet,repeated=false,kind=null){
 const groups=[];for(let i=0;i<sheet.rows.length;i+=3)groups.push(sheet.rows.slice(i,i+3));
 return `<div class="table-wrap"><table class="selection-summary-table"><thead><tr><th scope="col">집계 구분</th><th scope="col">사업 수</th><th scope="col">전체 사업비</th><th scope="col">2027~2032년 투자액</th><th scope="col">해당 기간 국비 요구액</th></tr></thead><tbody>${groups.map(rs=>`<tr><th scope="row">${kind?`<button class="summary-drill" data-summary-name="${E(rs[0][0])}" data-summary-kind="${kind}" aria-pressed="${selectedSummaryFilter?.kind===kind&&selectedSummaryFilter?.name===rs[0][0]}" aria-controls="selected-drilldown">${E(rs[0][0])}<span>선택 사업 ${N(rs[0][1])}건 보기 →</span></button>`:E(rs[0][0])}</th><td class="num">${N(rs[0][1])}<small>${repeated||rs[0][0]==='부처별 반복 합계'||rs[0][0]==='추가 반복분'?'회':'건'}</small></td>${rs.map(r=>`<td class="num"><strong>${r[3]===null?'—':N(r[3])}</strong><span class="summary-known">금액 포함 ${N(r[4])} · 잠정채택 ${N(r[5])}</span><span class="summary-pending ${r[6]||r[7]?'has-pending':''}">보류 ${N(r[6])} · 기타 미확인 ${N(r[7])}</span></td>`).join('')}</tr>`).join('')||'<tr><td colspan="5">집계할 부처 연결이 없습니다.</td></tr>'}</tbody></table></div>`;
}
function refreshSelectedSummary(){
 const holder=document.querySelector('#selected-summary');if(!holder)return;
 const ps=D.projects.filter(p=>selectedProjects.has(p.id)),signature=JSON.stringify([ps.map(p=>p.id),selectedSummaryGroup,selectedSummaryFilter]);if(holder.dataset.signature===signature)return;holder.dataset.signature=signature;
 if(!ps.length){holder.innerHTML='<section class="card selection-summary"><h2>선택 사업 요약</h2><p>사업을 담으면 권역별·부처별 사업 수와 예산을 여기에서 바로 확인할 수 있습니다.</p><a class="button" href="#projects">사업 검색에서 담기 →</a></section>';return}
 const sheets=selectionSummarySheets(ps,ministryRows);
 holder.innerHTML=`<section class="card selection-summary" aria-labelledby="selected-summary-title"><div class="summary-heading"><div><p class="eyebrow">선택한 ${N(ps.length)}개 사업만 집계</p><h2 id="selected-summary-title">선택 사업 요약</h2></div><span>금액 단위: 억원 · 부분합</span></div><p>엑셀 요약과 같은 기준입니다. 사업을 담거나 선택을 해제하면 바로 갱신됩니다.</p>${selectedSummaryTable(sheets[0])}<div class="summary-explainer"><p><strong>중복 제거:</strong> 사업 ID당 한 번 집계합니다. 부처 연결 없는 사업도 전체 합계에 포함합니다.</p><p><strong>부처별 반복 합계:</strong> 서로 다른 원문 부처 표기마다 한 번씩 집계합니다. 추가 반복분은 부처 연결 사업의 중복 제거 합계와의 차이이며, 실제 중복 재원이나 추가 예산을 뜻하지 않습니다.</p><p><strong>보류·기타 미확인:</strong> 금액 합계에서 제외하고 건수로 표시합니다. 포함 가능한 금액이 없으면 —로 표시하며, 실제 0원과 구분합니다. 잠정채택은 금액 포함 건수의 일부입니다. 반복 합계의 건수도 반복을 포함합니다.</p></div></section><section class="card selection-summary" aria-labelledby="selected-group-title"><div class="summary-heading"><h2 id="selected-group-title">${selectedSummaryGroup==='region'?'권역별':'원문 부처별'} 요약</h2><div class="summary-switch" role="group" aria-label="요약 분류"><button data-summary-group="region" aria-pressed="${selectedSummaryGroup==='region'}">권역별</button><button data-summary-group="ministry" aria-pressed="${selectedSummaryGroup==='ministry'}">부처별</button></div></div><p>${selectedSummaryGroup==='region'?'권역별 사업 수·예산의 합은 선택 전체의 중복 제거 합계와 같습니다.':'요약서·상세서 원문 표기 기준입니다. 같은 표기의 문서 간 중복은 제거하며, 약칭·정식 명칭은 합치지 않습니다. 각 부처 안에서는 사업당 1건, 부처 간 합계에는 반복이 포함됩니다.'}</p><p class="summary-click-help">권역 또는 부처 이름을 누르면 해당하는 선택 사업만 아래에 펼쳐집니다.</p>${selectedSummaryTable(sheets[selectedSummaryGroup==='region'?1:2],false,selectedSummaryGroup)}<div id="selected-drilldown">${selectedDrilldown(ps)}</div></section>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-summary-group]');if(!b)return;selectedSummaryGroup=b.dataset.summaryGroup;selectedSummaryFilter=null;refreshSelectedSummary();document.querySelector(`[data-summary-group="${selectedSummaryGroup}"]`)?.focus()});

function selectedDrilldownProjects(ps,filter,records){
 if(!filter)return [];
 const ids=new Set(records.filter(r=>r.label===filter.name).map(r=>r.id));
 return [...new Map(ps.filter(p=>filter.kind==='region'?(p.region||'권역 미기재')===filter.name:ids.has(p.id)).map(p=>[p.id,p])).values()];
}
function selectedDrilldown(ps){
 if(!selectedSummaryFilter)return '';
 const f=selectedSummaryFilter,rows=selectedDrilldownProjects(ps,f,ministryRows);
 return `<section class="selected-drill-panel" aria-labelledby="selected-drill-title"><div class="summary-heading"><div><small>현재 선택한 사업 안에서만 보기</small><h3 id="selected-drill-title" tabindex="-1">${E(f.name)} · 선택 사업 ${N(rows.length)}건</h3></div><div class="actions"><button class="primary" data-export-drill ${exportBusy||!rows.length?'disabled':''}>펼친 ${N(rows.length)}개 사업만 엑셀 ↓</button><button data-summary-close>목록 닫기</button></div></div><p>전체 선택 ${N(ps.length)}건 중 ${N(rows.length)}건입니다. 이곳의 다운로드 버튼은 펼친 사업만 담습니다. 전체 선택은 유지됩니다.</p><p>요약·원문 근거·공개자료·확인 수준을 항상 함께 넣습니다. 부처별 요약은 해당 사업에 연결된 모든 원문 부처 표기를 포함합니다.</p><p data-drill-export-status role="status">${E(exportStatus)}</p><div class="selected-drill-grid">${rows.map(p=>`<article class="selected-drill-project"><small>${E(p.region)} · ${E(p.id)}</small><h4><a href="${link(p,'graph')}">${E(p.title)} →</a></h4><p>원문 근거 ${N(p.source_count)}개 · ${E(p.detail_match||'상세서 연결 미확인')}</p><p class="source-meta">공개자료 확인: ${E(p.public_status||'미확인')}</p><details><summary>원문 부처 표기·연결 근거</summary>${f.kind==='ministry'?ministryRows.filter(r=>r.id===p.id&&r.label===f.name).map(r=>`<p><b>${r.origin==='summary'?'요약서':'상세서'}</b> ${E(r.raw)}</p><small>${E(r.source)} · ${E(r.location)} · 근거 ${E(r.evidence||'미기재')}</small>`).join(''):`<p>요약서: ${E(p.summary_ministry||'미기재')}</p><p>상세서: ${E(p.detail_ministry||'미기재')}</p>`}</details><a class="button" href="${link(p,'graph')}">원문 근거·확인 수준 보기 →</a></article>`).join('')||'<p class="empty">현재 선택한 사업 중 이 항목에 해당하는 사업이 없습니다.</p>'}</div></section>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-summary-name],[data-summary-close]');if(!b)return;
 if(b.hasAttribute('data-summary-close')){selectedSummaryFilter=null;refreshSelectedSummary();document.querySelector('[data-summary-group][aria-pressed=true]')?.focus();return}
 selectedSummaryFilter={kind:b.dataset.summaryKind,name:b.dataset.summaryName};refreshSelectedSummary();const title=document.querySelector('#selected-drill-title');title?.focus({preventScroll:true});title?.scrollIntoView({behavior:'smooth',block:'start'});
});

document.addEventListener('click',e=>{if(!e.target.closest('[data-export-drill]')||!selectedSummaryFilter)return;e.preventDefault();exportSelection({...selectedSummaryFilter})});

const selectionKey='regional-evidence-selected-projects',selectedProjects=new Set();let exportBusy=false,includeExportSources=true,exportStatus='';
try{const saved=JSON.parse(localStorage.getItem(selectionKey)||'[]');if(Array.isArray(saved))saved.forEach(id=>{if(P.has(id))selectedProjects.add(id)})}catch{}
function selectionControl(id){return `<label class="project-select"><input type="checkbox" data-select-project="${E(id)}" ${selectedProjects.has(id)?'checked':''}> 엑셀에 담기</label>`}
function saveSelection(){try{localStorage.setItem(selectionKey,JSON.stringify([...selectedProjects]))}catch{}refreshSelection()}
function refreshSelection(){document.querySelectorAll('[data-select-project]').forEach(c=>c.checked=selectedProjects.has(c.dataset.selectProject));const n=selectedProjects.size;let bar=document.querySelector('#selection-bar');if(!bar){bar=document.createElement('div');bar.id='selection-bar';bar.setAttribute('role','region');bar.setAttribute('aria-label','선택 사업 내보내기');document.body.append(bar)}bar.hidden=!n&&!exportBusy;document.body.classList.toggle('has-selection',n>0||exportBusy);bar.innerHTML=`<strong>${N(n)}개 사업 선택</strong><a class="button" href="#selected">선택 목록</a><button class="primary" data-export-selected ${!n||exportBusy?'disabled':''}>${exportBusy?'엑셀 만드는 중…':'선택 사업 엑셀 ↓'}</button><button data-clear-selection ${exportBusy?'disabled':''}>선택 비우기</button><span role="status" aria-live="polite">${E(exportStatus)}</span>`;document.querySelectorAll('[data-selection-count]').forEach(el=>el.textContent=N(n));document.querySelectorAll('[data-export-selected]').forEach(el=>el.disabled=!n||exportBusy);refreshSelectedSummary();document.querySelectorAll('[data-export-drill]').forEach(el=>el.disabled=exportBusy||!selectedDrilldownProjects(D.projects.filter(p=>selectedProjects.has(p.id)),selectedSummaryFilter,ministryRows).length);document.querySelectorAll('[data-drill-export-status]').forEach(el=>el.textContent=exportStatus)}
function selectedPage(){const rows=D.projects.filter(p=>selectedProjects.has(p.id));main.innerHTML=heading('선택 사업 요약·내려받기','선택한 사업의 권역별·부처별 사업 수와 예산을 확인하고, 같은 요약을 엑셀로 내려받습니다.')+`<div class="selection-options card"><strong><span data-selection-count>${rows.length}</span>개 사업 선택</strong><label><input id="include-export-sources" type="checkbox" ${includeExportSources?'checked':''}> 원문·공개 근거 포함</label><button class="primary" data-export-selected ${!rows.length||exportBusy?'disabled':''}>선택 사업 엑셀 내려받기</button><button data-clear-selection>선택 비우기</button></div><div id="selected-summary" aria-live="polite"></div><div class="notice">항상 포함: 선택요약·권역별요약·부처별요약. 중복 제거 합계와 부처별 반복 합계, 부처 연결 없는 사업을 구분하며 예산별 보류·기타 미확인 건수를 표시합니다. 보류·미확인 금액은 합계에서 제외합니다.<br>기본정보: 사업명·권역·원문 부처·세 가지 예산·확인 상태·출처. 근거 포함 시 부처 원문, 원문 인용, 공개자료의 URL·열람 수준을 별도 시트에 담습니다. 금액 빈칸은 미확인이며 0이 아닙니다.</div><div class="card table-wrap"><table><thead><tr><th>선택</th><th>사업</th><th>전체 사업비</th><th>기간 투자액</th><th>국비 요구액</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${selectionControl(p.id)}</td><td><small>${E(p.id)}</small><br><a href="${link(p)}">${E(p.title)}</a></td>${['whole','window','national'].map(k=>`<td class="num">${N(p[k])}<span class="count-note">${E(p[k+'_status'])}</span></td>`).join('')}</tr>`).join('')||'<tr><td colspan="5">선택한 사업이 없습니다. <a href="#projects">사업 검색에서 담기 →</a></td></tr>'}</tbody></table></div>`;document.querySelector('#include-export-sources').onchange=e=>includeExportSources=e.target.checked;refreshSelection()}
function attachSelectionControls(){let changed=false;
 document.querySelectorAll('.results-table tbody tr').forEach(row=>{if(row.dataset.selectionReady)return;const a=row.querySelector('.project-title a');if(!a)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;row.dataset.selectionReady='1';const td=document.createElement('td');td.innerHTML=selectionControl(id);row.prepend(td);changed=true});const th=document.querySelector('.results-table thead tr');if(th&&!th.dataset.selectionReady){th.dataset.selectionReady='1';th.insertAdjacentHTML('afterbegin','<th>選択</th>'.replace('選択','선택'));changed=true}
 document.querySelectorAll('.hub-project-card').forEach(a=>{if(a.dataset.selectionReady)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;a.dataset.selectionReady='1';const wrap=document.createElement('div');wrap.className='selection-card-wrap';a.before(wrap);wrap.innerHTML=selectionControl(id);wrap.append(a);changed=true});
 document.querySelectorAll('.multi-project').forEach(el=>{if(el.dataset.selectionReady)return;const a=el.querySelector('h3 a');if(!a)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;el.dataset.selectionReady='1';el.insertAdjacentHTML('afterbegin',selectionControl(id));changed=true});
 document.querySelectorAll('.project-head,.relationship-map').forEach(el=>{if(el.dataset.selectionReady)return;const routeId=location.hash.split('/')[1]?.split('?')[0],id=routeId?decodeURIComponent(routeId):D.projects[0].id;if(!P.has(id))return;el.dataset.selectionReady='1';el.insertAdjacentHTML('afterbegin',selectionControl(id));changed=true});
 const search=document.querySelector('#search-form');if(search&&!document.querySelector('#selection-search-tools')){search.insertAdjacentHTML('afterend','<div id="selection-search-tools" class="selection-search-tools"><button data-select-results>검색 결과 전체 담기</button><button data-select-visible>현재 페이지 담기</button><a class="button" href="#selected">선택 목록·엑셀 ↓</a><small>기존 선택에 추가합니다.</small></div>');changed=true}
 if(changed)refreshSelection();
}
function sourceChunks(v){const s=String(v??''),out=[];let i=0;while(i<s.length){let end=Math.min(i+30000,s.length);if(end<s.length&&/[\uD800-\uDBFF]/.test(s[end-1]))end--;out.push(s.slice(i,end));i=end}return out.length?out:['']}
function selectionSheets(ps,packets,withSources){
 ps=[...new Map(ps.map(p=>[p.id,p])).values()];
 const sheets=[{name:'선택사업',headers:['사업 ID','권역','구분','사업명','요약서 부처 원문','상세서 부처 원문','전체 사업비 (억원)','전체 사업비 상태','2027~2032 투자액 (억원)','기간 투자액 상태','해당 기간 국비 요구액 (억원)','국비 요구액 상태','요약서 사업기간','상세서 사업기간','상세서 연결 방식','공개자료 확인 상태','요약서 파일','요약서 위치','상세서 파일','상세서 위치','사업 내용','사업 상세 링크'],widths:[25,14,14,65,35,45,22,17,24,17,26,17,25,35,24,45,55,30,55,30,90,60],rows:ps.map(p=>[p.id,p.region,p.category,p.title,p.summary_ministry,p.detail_ministry,p.whole,p.whole_status,p.window,p.window_status,p.national,p.national_status,p.period,p.detail_period,p.detail_match,p.public_status,p.summary_source,p.summary_location,p.detail_source,p.detail_location,p.summary_body,new URL(link(p),window.location.href).href])}];
 sheets.unshift(...selectionSummarySheets(ps,ministryRows));
 if(withSources){const ids=new Set(ps.map(p=>p.id));sheets.push({name:'부처원문',headers:['사업 ID','부처 표기','기재 문서','원문 부처 항목','파일','위치','근거 ID','상세서 연결 상태'],widths:[25,25,15,70,60,35,25,25],rows:ministryRows.filter(r=>ids.has(r.id)).map(r=>[r.id,r.label,r.origin==='summary'?'요약서':'상세서',r.raw,r.source,r.location,r.evidence,r.detail_match])});
 sheets.push({name:'원문근거',headers:['사업 ID','근거 ID','항목','파일','위치','인용 부분','원문 인용','확인 수준'],widths:[25,18,22,60,30,15,110,30],rows:packets.flatMap(d=>d.evidence.flatMap(e=>sourceChunks(e.excerpt).map((chunk,i,a)=>[d.id,e.evidence_id,e.field,e.source,e.location,`${i+1}/${a.length}`,chunk,'원문 기재 · 실제 집행·승인 미확인'])))});
 sheets.push({name:'공개자료',headers:['사업 ID','출처 ID','자료명','URL','발행 도메인','확인일','열람 수준','사업과 관계','발췌 부분','발췌 내용','확인 범위','동일사업 여부'],widths:[25,18,65,90,30,18,60,45,15,100,80,25],rows:packets.flatMap(d=>d.sources.flatMap(s=>sourceChunks(s.excerpt).map((chunk,i,a)=>[d.id,s.source_id,s.title,s.url,s.publisher_domain,s.checked,s.read_level,d.public.find(r=>r.source_id===s.source_id)?.relation||'기존 참고자료',`${i+1}/${a.length}`,chunk,s.field_scope,'미확인'])))});
 }
 sheets.push({name:'읽기안내',headers:['항목','내용'],widths:[32,110],rows:[['분석 기준일','2026-10-30'],['선택 사업 수',ps.length],['내보낸 시각',new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' (한국시간)'],['예산 단위','억원. 전체 사업비·2027~2032년 투자액·해당 기간 국비 요구액을 구분합니다.'],['빈칸과 보류','금액 빈칸은 미확인입니다. 0으로 치환하지 않았습니다. 상태 열의 보류·잠정채택 등을 함께 확인하세요.'],['부처 표기','요약서·상세서 원문 기준이며 실제 소관 확정이 아닙니다. 약칭과 정식 명칭은 통합하지 않았습니다.'],['공개자료','검색 발췌와 원문 열람 수준은 자료별 열에 표시합니다. 연결이 동일사업·동일재원을 의미하지 않습니다.'],['원문 인용','셀 글자 수 제한을 넘는 긴 인용은 순번을 붙여 여러 행으로 나눕니다.'],['근거 포함',withSources?'포함':'기본정보·요약만'],['요약 집계','선택요약·권역별요약·부처별요약은 항상 포함하며 다운로드 시점의 고정 집계입니다. 사업 수는 예산 항목마다 반복되므로 세 예산 행의 사업 수를 더하지 마세요.'],['부분합과 미확인','집계 가능 금액은 보류와 기타 미확인을 제외한 부분합입니다. 보류는 상태에 보류가 표시된 항목, 기타 미확인은 보류 외 금액 미확인 항목입니다. 미확인 금액은 산출하지 않고 건수로 표시합니다. 포함 가능한 금액이 전혀 없으면 부분합도 빈칸입니다. 잠정채택은 포함 금액 중 별도 건수로 표시합니다.'],['반복 합계','부처별 반복 합계는 서로 다른 원문 부처 표기마다 사업을 한 번씩 집계합니다. 추가 반복분은 부처 연결 사업의 중복 제거 합계와의 차이이며 실제 중복 재원이나 추가 예산을 뜻하지 않습니다. 부처 연결 없는 사업은 전체 합계에만 포함합니다.'],['사업 중복','사업 ID별 한 번만 내보냅니다. 부처 원문·근거 시트에는 한 사업의 여러 근거가 반복 행으로 나타납니다.']]});return sheets;
}
async function exportSelection(scope=null){if(exportBusy||!selectedProjects.size)return;const selected=D.projects.filter(p=>selectedProjects.has(p.id)),ps=scope?selectedDrilldownProjects(selected,scope,ministryRows):selected,withSources=scope?true:includeExportSources;if(!ps.length)return;exportBusy=true;exportStatus='자료 준비 중…';refreshSelection();try{const packets=[];if(withSources){for(let i=0;i<ps.length;i+=6){const batch=await Promise.all(ps.slice(i,i+6).map(p=>packet(p.id)));packets.push(...batch);exportStatus=`근거 불러오기 ${Math.min(i+6,ps.length)} / ${ps.length}`;refreshSelection();await new Promise(r=>setTimeout(r,0))}}const sheets=selectionSheets(ps,packets,withSources);if(scope)sheets.find(s=>s.name==='읽기안내').rows.push(['내보내기 범위',(scope.kind==='region'?'권역':'원문 부처 표기')+': '+scope.name+' · 다운로드 버튼을 누른 시점의 펼친 선택 사업 '+ps.length+'건'],['부처별 요약 범위','이 파일에 담긴 사업에 연결된 모든 원문 부처 표기를 집계합니다. 눌렀던 부처만으로 제한하지 않습니다.'],['근거 포함 범위','펼친 사업만 내보내기에는 원문·공개 근거와 확인 수준이 항상 포함됩니다.']);exportStatus='엑셀 파일 생성 중…';refreshSelection();await new Promise(r=>setTimeout(r,0));const blob=window.AtlasXlsx.workbook(sheets),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`${scope?'펼친사업_'+(scope.kind==='region'?'권역':'부처')+'_'+scope.name.replace(/[\\/:*?"<>|]/g,'_'):'선택사업'}_${ps.length}건_${new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})}.xlsx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);exportStatus=`${scope?scope.name+' · 펼친 사업 ':''}${ps.length}개 사업의 엑셀 다운로드를 시작했습니다.`}catch(e){exportStatus='내려받기에 실패했습니다. 선택은 유지됩니다. 다시 시도해 주세요.';console.error('Excel export failed',e)}finally{exportBusy=false;refreshSelection()}}
document.addEventListener('change',e=>{const id=e.target?.dataset?.selectProject;if(!id||!P.has(id))return;e.target.checked?selectedProjects.add(id):selectedProjects.delete(id);saveSelection()});
document.addEventListener('click',e=>{const t=e.target.closest('[data-export-selected],[data-clear-selection],[data-select-results],[data-select-visible]');if(!t)return;e.preventDefault();if(t.hasAttribute('data-export-selected'))exportSelection();else if(t.hasAttribute('data-clear-selection')){selectedProjects.clear();exportStatus='';saveSelection();if(location.hash==='#selected')selectedPage()}else{const ids=t.hasAttribute('data-select-results')?window.ACTIVE_SELECTION_RESULTS||[]:[...document.querySelectorAll('.results-table [data-select-project]')].map(c=>c.dataset.selectProject);ids.forEach(id=>{if(P.has(id))selectedProjects.add(id)});saveSelection()}});
window.addEventListener('storage',e=>{if(e.key!==selectionKey)return;try{const saved=JSON.parse(e.newValue||'[]');selectedProjects.clear();saved.forEach(id=>{if(P.has(id))selectedProjects.add(id)});refreshSelection();if(location.hash==='#selected')selectedPage()}catch{}});
new MutationObserver(attachSelectionControls).observe(main,{childList:true,subtree:true});refreshSelection();




let serial=0;async function route(){let token=++serial,raw=location.hash.slice(1)||'overview',[path,q]=raw.split('?'),[name,id]=path.split('/'),p=id?P.get(decodeURIComponent(id)):D.projects[0];document.body.classList.remove('menu-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(name==='project'?'projects':name)));document.querySelector('#breadcrumb').textContent={overview:'전체 개요',selected:'선택 사업·엑셀 다운로드',multiple:'복수 부처 연결·반복 집계',compare:'사업 수·예산 비교',explore:'권역·부처별 연결 사업',projects:'사업 검색',project:'사업 검색 / 사업 상세',graph:'지식그래프',sources:'근거 자료실',method:'확인 수준·분석 기준',downloads:'자료 내려받기'}[name]||'사업과 근거';main.innerHTML='<div class="loading">근거 데이터를 불러오고 있습니다…</div>';window.scrollTo(0,0);try{if(name==='overview')overview();else if(name==='selected')selectedPage();else if(name==='multiple')multiMinistry(new URLSearchParams(q));else if(name==='compare')budgetCompare(new URLSearchParams(q));else if(name==='explore')explore(new URLSearchParams(q));else if(name==='projects')projects(new URLSearchParams(q));else if(name==='project'&&p)await detail(p,token);else if(name==='graph'&&p)await graph(p,token);else if(name==='sources')await sourcePage(token);else if(name==='method')method();else if(name==='downloads')downloads();else main.innerHTML='<div class="empty">사업 또는 페이지를 찾을 수 없습니다.<p><a href="#projects">전체 사업으로 이동</a></p></div>'}catch(e){if(token===serial)main.innerHTML=`<div class="empty error">${E(e.message)}<p><a href="#overview">전체 개요로 돌아가기</a></p></div>`}}
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus()};document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus()};document.querySelector('#region-nav').innerHTML=D.regions.map(r=>`<a href="${hubLink('region',r.region)}">${E(r.region)}<small>${r.count}</small></a>`).join('');document.querySelector('#menu-toggle').onclick=()=>{let open=document.body.classList.toggle('menu-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',open)};window.addEventListener('hashchange',route);route();
